add_filter( 'woocommerce_get_price_html', 'perfectpixel_was_now_save_prices', 20, 2 );

function perfectpixel_was_now_save_prices( $html, $product ) {
	if ( ! $product || ! $product->is_type( 'simple' ) || ! $product->is_on_sale() ) {
		return $html;
	}
	$regular = (float) wc_get_price_to_display( $product, array( 'price' => $product->get_regular_price() ) );
	$sale    = (float) wc_get_price_to_display( $product );
	if ( $regular <= $sale ) {
		return $html;
	}
	return sprintf(
		'<span class="perfectpixel-was">%1$s <del>%2$s</del></span> <span class="perfectpixel-now">%3$s <ins>%4$s</ins></span> <span class="perfectpixel-save" style="color:#d63638">%5$s %6$s</span>%7$s',
		esc_html( '{{was_label}}' ),
		wc_price( $regular ),
		esc_html( '{{now_label}}' ),
		wc_price( $sale ),
		esc_html( '{{save_label}}' ),
		wc_price( $regular - $sale ),
		$product->get_price_suffix()
	);
}
